const items = $json.items || [];
if (items.length === 0) return [];

return items.map(item => ({
  ...item,
  // Default enrichment fields
  enriched: false,
  score: 0,
  personalizedEmail: '',
  emailSubject: '',
  painPoints: []
}));

const lead = $json;
const website = lead.website || '';

let siteContent = '';
let siteIssues = [];

if (website) {
  try {
    const resp = await fetch(website, { signal: AbortSignal.timeout(8000) });
    siteContent = await resp.text();

    // Basic checks
    if (!siteContent.includes('application/ld+json') && !siteContent.includes('itemscope'))
      siteIssues.push('missing_structured_data');
    if (!siteContent.includes('viewport'))
      siteIssues.push('not_mobile_friendly');
    if (siteContent.length < 500)
      siteIssues.push('thin_content');
    if (!siteContent.includes('https://') && !siteContent.includes('http://'))
      siteIssues.push('http_not_https');
  } catch (e) {
    siteIssues.push('site_unreachable');
  }
}

return [{
  ...lead,
  siteSnippet: siteContent.substring(0, 3000),
  siteIssues: siteIssues.join(', '),
  hasStructuredData: !siteIssues.includes('missing_structured_data'),
  mobileFriendly: !siteIssues.includes('not_mobile_friendly'),
  reachable: !siteIssues.includes('site_unreachable')
}];

const ai = $json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(ai);
} catch {
  const match = ai.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}

const lead = $node['Scrape & Check Website'].json;

return [{
  ...lead,
  aiScore: parsed.score || 50,
  painPoints: (parsed.painPoints || []).join('; '),
  valueProposition: parsed.valueProposition || '',
  personalizedEmail: parsed.personalizedEmail || '',
  emailSubject: parsed.emailSubject || '',
  hasAiVisibility: parsed.hasAiVisibility || false,
  enrichedAt: new Date().toISOString(),
  status: (parsed.score || 0) >= 50 ? 'qualified' : 'low_priority'
}];
